.darma-loader-tw-step-progress { display: flex; align-items: center; width: var(--loader-size, 180px); }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__step { flex: none; width: calc(var(--loader-size, 180px) * .13); height: calc(var(--loader-size, 180px) * .13); border-radius: 9999px; background: var(--loader-color, #0ea5e9); opacity: .3; animation: darma-loader-tw-step-progress-twStep calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__step:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * 1); }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__step:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * 2); }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__line { position: relative; flex: 1; height: calc(var(--loader-size, 180px) * .025); overflow: hidden; background: color-mix(in srgb, var(--loader-color, #0ea5e9) 22%, transparent); }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__line::after { content: ''; position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: var(--loader-color, #0ea5e9); transform-origin: left center; animation: darma-loader-tw-step-progress-twStepLine calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__line:nth-child(2)::after { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-tw-step-progress .darma-loader-tw-step-progress__line:nth-child(4)::after { animation-delay: calc(var(--loader-speed, 1s) * 1.3); }
@keyframes darma-loader-tw-step-progress-twStep { 0%, 20% { opacity: .3; transform: scale(.82); } 30%, 100% { opacity: 1; transform: scale(1); } }
@keyframes darma-loader-tw-step-progress-twStepLine { 0%, 10% { transform: scaleX(0); } 30%, 100% { transform: scaleX(1); } }

